import React from 'react';

import { Breadcrumb, BreadcrumbProps } from 'react-bootstrap';
import { Link } from 'react-router-dom';

interface IBreadcrumbItem {
  text: string;
  href: string;
  active?: boolean;
}

interface IPohBreadcrumbs extends BreadcrumbProps {
  data: Array<IBreadcrumbItem>;
}

const PohBreadcrumbs: React.FC<IPohBreadcrumbs> = ({ data, children, ...props }) => {
  return (
    <Breadcrumb {...props}>
      {data.map(({ text, href, ...rest }) =>
        React.createElement(
          Breadcrumb.Item,
          {
            linkAs: Link,
            href: href || '',
            key: href || text,
            linkProps: { to: href },
            ...rest,
          },
          text,
        ),
      )}
      {children}
    </Breadcrumb>
  );
};

export default PohBreadcrumbs;
